// End-to-end file-rule scenarios F1-F17 and B1 for every language (LAB-7587).
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { EXT, LANGS, baselineJson as bj, check, commit, file, fn, initRepo, makeRepo, run, runCli, source, write } from "./scenario-kit.mjs";

const B = ".github/size-baseline.json";
// Every repo carries one small in-scope file so the liveness floor holds.
const repo = (lang, base, head, untracked) =>
  makeRepo({ base: { [`keep.${EXT[lang]}`]: file(lang, 3), ...base }, head, untracked });

for (const lang of LANGS) {
  const p = `d/a.${EXT[lang]}`;
  test(`${lang} F1: a new 501-line file warns without failing`, () => {
    const r = check(repo(lang, {}, { [p]: file(lang, 501) }));
    assert.equal(r.code, 0, r.out);
    assert.match(r.out, new RegExp(`::warning file=${p}::${p} is 501 lines, over the 400-line advisory threshold`));
    assert.doesNotMatch(r.out, /::error /);
  });
  test(`${lang} F2: a new 500-line file passes with a warning`, () => {
    const r = check(repo(lang, {}, {}, { [p]: file(lang, 500) }));
    assert.equal(r.code, 0, r.out);
    assert.match(r.out, new RegExp(`::warning file=${p}::${p} is 500 lines, over the 400-line advisory threshold`));
  });
  test(`${lang} F3: an unbaselined file grown 150 to 410 passes with a warning`, () => {
    const r = check(repo(lang, { [p]: file(lang, 150) }, { [p]: file(lang, 410) }));
    assert.equal(r.code, 0, r.out);
    assert.match(r.out, /is 410 lines, over the 400-line advisory threshold/);
  });
  test(`${lang} F4: a baselined file that grows warns without failing`, () => {
    const r = check(repo(lang, { [p]: file(lang, 600), [B]: bj({ [p]: 600 }) }, { [p]: file(lang, 605) }));
    assert.equal(r.code, 0, r.out);
    assert.match(r.out, new RegExp(`::warning file=${p}::${p} is 605 lines, over the 400-line advisory threshold`));
  });
  test(`${lang} F5: a shrink need not lower an obsolete baseline entry`, () => {
    const base = { [p]: file(lang, 600), [B]: bj({ [p]: 600 }) };
    const kept = check(repo(lang, base, { [p]: file(lang, 590) }));
    assert.equal(kept.code, 0, kept.out);
    assert.match(kept.out, /is 590 lines, over the 400-line advisory threshold/);
    const lowered = check(repo(lang, base, { [p]: file(lang, 590), [B]: bj({ [p]: 590 }) }));
    assert.equal(lowered.code, 0, lowered.out);
  });
  test(`${lang} F6: adding or raising a legacy entry cannot fail the size check`, () => {
    const base = { [p]: file(lang, 600), [B]: bj({ [p]: 600 }) };
    const raised = check(repo(lang, base, { [p]: file(lang, 610), [B]: bj({ [p]: 610 }) }));
    assert.equal(raised.code, 0, raised.out);
    assert.match(raised.out, /is 610 lines, over the 400-line advisory threshold/);
    const q = `d/b.${EXT[lang]}`;
    const added = check(repo(lang, base, { [q]: file(lang, 550), [B]: bj({ [p]: 600, [q]: 550 }) }));
    assert.equal(added.code, 0, added.out);
    assert.match(added.out, new RegExp(`::warning file=${q}::${q} is 550 lines`));
  });
  test(`${lang} F7: a stale baseline entry cannot cause a source-length failure`, () => {
    const r = check(repo(lang, { [p]: file(lang, 600), [B]: bj({ [p]: 600 }) }, { [p]: file(lang, 290) }));
    assert.equal(r.code, 0, r.out);
    assert.doesNotMatch(r.out, /::warning file=/);
  });
  test(`${lang} F10: exclude-paths and include-paths take files out of scope`, () => {
    const big = { [p]: file(lang, 600) };
    assert.equal(check(repo(lang, {}, big), { SIZE_GATE_EXCLUDE: "d/**" }).code, 0);
    assert.equal(check(repo(lang, {}, big), { SIZE_GATE_INCLUDE: `keep.${EXT[lang]}` }).code, 0);
    assert.equal(check(repo(lang, {}, big), {}, ["--exclude", "d/**"]).code, 0);
  });
}

test("F8: 600-line test files are out of scope", () => {
  const big = (lang) => file(lang, 600);
  const head = {
    "x_test.go": big("go"),
    "x.test.ts": big("ts"),
    "x.spec.tsx": big("tsx"),
    "test_x.py": big("py"),
    "x_test.py": big("py"),
    "conftest.py": big("py"),
    "x.test.mjs": big("mjs"),
    "x.spec.js": big("js"),
    "vendor.min.js": big("js"),
    "__tests__/a.jsx": big("jsx"),
    "test-utils.cjs": big("cjs"),
  };
  const r = check(repo("go", {}, head));
  assert.equal(r.code, 0, r.out);
  assert.doesNotMatch(r.out, /::(error|warning)/);
});

test("F8: only *.min.js is exempt as bundled; a 600-line app.min.mjs warns", () => {
  const r = check(repo("go", {}, { "app.min.mjs": file("mjs", 600) }));
  assert.equal(r.code, 0, r.out);
  assert.match(r.out, /::warning file=app\.min\.mjs::app\.min\.mjs is 600 lines/);
});

test("F9: a generated Go file is exempt; the same file without the header is not", () => {
  const gen = file("go", 600, "// Code generated by x. DO NOT EDIT.").replace("// filler 0", "package p");
  assert.equal(check(repo("go", {}, { "g.go": gen })).code, 0);
  const handwritten = check(repo("go", {}, { "g.go": file("go", 600) }));
  assert.equal(handwritten.code, 0, handwritten.out);
  assert.match(handwritten.out, /::warning file=g\.go/);
});

test("F11: scanning fewer files than min-scanned-files fails", () => {
  const r = check(repo("py", {}, { "b.py": file("py", 3) }), { SIZE_GATE_MIN_SCANNED: "5" });
  assert.equal(r.code, 1);
  assert.match(r.out, /::error::size gate scanned 2 files; expected ≥ 5 — the scope is wrong/);
});

test("F12: a baseline entry that is not a line count fails the gate, at HEAD or the merge-base", () => {
  const p = "d/a.go";
  const bad = JSON.stringify({ files: { [p]: "x" } });
  for (const [base, head] of [[{ [p]: file("go", 600) }, { [B]: bad }], [{ [p]: file("go", 600), [B]: bad }, { [B]: bj({ [p]: 600 }) }]]) {
    const r = check(repo("go", base, head));
    assert.equal(r.code, 1);
    assert.match(r.out, /::error::.*size-baseline\.json: entry "d\/a\.go" is "x"; it must be a non-negative integer line count/);
  }
});

test("F13: a newly introduced legacy baseline is informational", () => {
  const big = { "d/a.go": file("go", 600) };
  assert.equal(check(repo("go", big, { [B]: bj({ "d/a.go": 600 }) })).code, 0);
  const renamed = check(repo("go", big, { "d/a.go": null, "d/n.go": file("go", 600), [B]: bj({ "d/n.go": 600 }) }));
  assert.equal(renamed.code, 0, renamed.out);
  const added = check(repo("go", {}, { "d/b.go": file("go", 600), [B]: bj({ "d/b.go": 600 }) }));
  assert.equal(added.code, 0, added.out);
  assert.match(added.out, /::warning file=d\/b\.go::d\/b\.go is 600 lines/);
  const grown = check(repo("go", { "d/a.go": file("go", 250) }, { "d/a.go": file("go", 600), [B]: bj({ "d/a.go": 600 }) }));
  assert.equal(grown.code, 0, grown.out);
  assert.match(grown.out, /::warning file=d\/a\.go::d\/a\.go is 600 lines/);
});

// A repo whose head commit adds `files` and the symlinks `links` (path -> target).
function linked(links, files = {}) {
  const root = initRepo();
  const base = commit(root, { "keep.go": file("go", 3) });
  write(root, files);
  for (const [p, target] of Object.entries(links)) {
    mkdirSync(path.dirname(path.join(root, p)), { recursive: true });
    symlinkSync(target, path.join(root, p));
  }
  commit(root, {});
  return { root, base };
}

test("F14: an in-scope symlink passes only when it resolves to an in-scope file in the checkout", () => {
  const rule = "an in-scope symlink must resolve to an in-scope file inside the checkout, which is then checked on its own";
  const outside = path.join(mkdtempSync(path.join(tmpdir(), "sg-out-")), "big.go");
  writeFileSync(outside, file("go", 400));
  const bad = [
    [{ "a.go": outside }, {}, {}, "a path outside the checkout"],
    [{ "a.go": "notes.txt" }, { "notes.txt": file("go", 400) }, {}, "`notes.txt`, which is not an in-scope file"],
    [{ "a.go": "missing.go" }, {}, {}, "a path that does not exist"],
    [{ "a.go": "vendor/big.go" }, { "vendor/big.go": file("go", 400) }, { SIZE_GATE_EXCLUDE: "vendor/**" }, "`vendor/big.go`, which is not an in-scope file"],
  ];
  for (const [links, files, env, why] of bad) {
    const r = check(linked(links, files), env);
    assert.equal(r.code, 1, r.out);
    assert.ok(r.out.includes(`::error file=a.go::a.go is a symlink to ${why}; ${rule}.`), r.out);
  }
  assert.equal(check(linked({ "a.go": "real/b.go" }, { "real/b.go": file("go", 10) })).code, 0);
  const big = check(linked({ "a.go": "real/b.go" }, { "real/b.go": file("go", 600) }));
  assert.equal(big.code, 0, big.out);
  assert.match(big.out, /::warning file=real\/b\.go::real\/b\.go is 600 lines/);
  assert.doesNotMatch(big.out, /file=a\.go/);
});

test("F15: a directory symlink passes only when every in-scope file it exposes is checked on its own", () => {
  const big = { "testdata/big/big.go": source("go", fn("go", "F", 120), fn("go", "G", 300)) };
  const r = check(linked({ "pkg/big": "../testdata/big" }, big));
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, /::error file=pkg\/big::pkg\/big is a symlink to a directory exposing `testdata\/big\/big\.go`, which is not an in-scope file; /);
  assert.equal(check(linked({ "pkg/alias": "../real" }, { "real/a.go": file("go", 10) })).code, 0);
  const away = check(linked({ "pkg/out": mkdtempSync(path.join(tmpdir(), "sg-dir-")) }));
  assert.match(away.out, /pkg\/out is a symlink to a directory outside the checkout; /);
  const nested = check(linked({ "real/in": "../keep.go", "pkg/alias": "../real" }, { "real/a.go": file("go", 3) }));
  assert.match(nested.out, /pkg\/alias is a symlink to a directory holding the symlink `real\/in`; /);
  const grown = check(linked({ "pkg/alias": "../real" }, { "real/a.go": file("go", 600) }));
  assert.equal(grown.code, 0, grown.out);
  assert.match(grown.out, /::warning file=real\/a\.go::real\/a\.go is 600 lines/);
  assert.doesNotMatch(grown.out, /file=pkg\/alias/);
});

test("F16: a directory symlink is checked whatever include-paths lists, against that scope", () => {
  const env = { SIZE_GATE_INCLUDE: "src/**/*.go" };
  const files = { "src/a.go": file("go", 3), "other/big.go": file("go", 400) };
  const r = check(linked({ "src/lib": "../other" }, files), env);
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, /::error file=src\/lib::src\/lib is a symlink to a directory exposing `other\/big\.go`, which is not an in-scope file; /);
  const away = check(linked({ "tools/lib": "../other" }, files), env);
  assert.equal(away.code, 0, away.out);
});

test("usage errors exit 2", () => {
  assert.equal(runCli(repo("go", {}, {}).root, ["bogus"]).code, 2);
});

test("B1: baseline mode writes exactly the files over 500 with their lengths", () => {
  const r = repo("go", {}, {
    "a.go": file("go", 501),
    "b.ts": file("ts", 500),
    "c/d.py": file("py", 650),
    "c/e_test.go": file("go", 700),
  });
  const out = runCli(r.root, ["baseline", "--baseline", "x/size.json"]);
  assert.equal(out.code, 0, out.out);
  assert.match(out.out, /wrote x\/size\.json: 2 files over 500 lines/);
  const body = JSON.parse(readFileSync(path.join(r.root, "x/size.json"), "utf8"));
  assert.deepEqual(body, {
    limit: 500,
    generatedBy: "node .github/actions/size-gate/cli.mjs baseline",
    files: { "a.go": 501, "c/d.py": 650 },
  });
  assert.deepEqual(Object.keys(body.files), ["a.go", "c/d.py"]);
});

// guard#9701: the base branch moved after base.sha; the merge ref carries
// those commits, and none of them may be attributed to the PR.
for (const lang of LANGS) {
  test(`${lang} F17: on pull_request, base-branch commits after base.sha are not the PR's`, () => {
    const [p, f] = [`d/a.${EXT[lang]}`, `d/f.${EXT[lang]}`];
    const root = initRepo();
    const fork = commit(root, { [`keep.${EXT[lang]}`]: file(lang, 3), [p]: file(lang, 600), [B]: bj({ [p]: 600 }), [f]: source(lang, fn(lang, "F", 60)) });
    run(root, "checkout", "-q", "-b", "feature");
    commit(root, { [`keep.${EXT[lang]}`]: file(lang, 4) });
    run(root, "checkout", "-q", "main");
    commit(root, { [p]: file(lang, 601), [B]: bj({ [p]: 601 }), [f]: source(lang, fn(lang, "F", 61)) });
    run(root, "merge", "-q", "--no-ff", "-m", "merge", "feature");
    const r = check({ root, base: fork }, { GITHUB_EVENT_NAME: "pull_request" });
    assert.equal(r.code, 0, r.out);
    assert.match(r.out, /::notice::HEAD is the pull_request merge ref; comparing with its first parent/);
    const push = check({ root, base: fork }, { GITHUB_EVENT_NAME: "push" });
    assert.equal(push.code, 0, push.out);
    assert.match(push.out, /::warning file=/);
  });
}
